@triton.jit
def block_diag_uniform_fused_kernel(
    out_ptr,
    src_ptr,
    ptrs_ptr,
    input_stride,
    block_rows,
    block_cols,
    row_tiles,
    n_blocks,
    total_cols,
    TR: tl.constexpr,
    TC: tl.constexpr,
    USE_PTRS: tl.constexpr,
):
    """Write the whole block-diagonal output in a single launch.

    Grid axis 0 tiles the row band of each diagonal block (band-uniform, so
    the source block index is a scalar per program); axis 1 tiles the full
    output width, so one program may cover several column blocks. The tile is
    written as three disjoint dense segments (left zeros / diagonal copy /
    right zeros): every access uses affine addresses plus prefix/suffix masks
    only. Window masks and overlapping stores must stay out of this kernel -
    both silently degrade or corrupt on GCU (see knowledge notes: window-mask
    DMA degradation; TR=128 x TC=512 miscompile).
    """
