    pid_c = ext.program_id(1)  # ceil(total_cols / TC)

    band = pid_r // row_tiles
    rt = pid_r % row_tiles
    r = rt * TR + tl.arange(0, TR)
    rmask = r < block_rows

    c0 = pid_c * TC
    out_c = c0 + tl.arange(0, TC)

    out_r = band * block_rows + r
    out_idx = out_r[:, None] * total_cols + out_c[None, :]

    diag_lo = band * block_cols
    diag_hi = diag_lo + block_cols

    dstart = tl.maximum(c0, diag_lo)
    dend = tl.minimum(c0 + TC, diag_hi)

    zero = tl.zeros((TR, TC), dtype=out_ptr.dtype.element_ty)

    # left zeros: [c0, dstart)
    if dstart > c0:
        lm = out_c < dstart
        tl.store(out_ptr + out_idx, zero, mask=rmask[:, None] & lm[None, :])

    # right zeros: [dend, c0 + TC), bounded by total_cols on the edge tile
    if dend < c0 + TC:
        rm = out_c >= dend
        if c0 + TC > total_cols:
            rm = rm & (out_c < total_cols)
        tl.store(out_ptr + out_idx, zero, mask=rmask[:, None] & rm[None, :])

    # diagonal copy: [dstart, dend)
